module min_transmission_cost (\n    input [2:0] N,\n    input [2:0] M,\n    input [7:0] adj_A_0, adj_A_1, adj_A_2, adj_A_3, adj_A_4, adj_A_5, adj_A_6, adj_A_7,\n    input [7:0] adj_B_0, adj_B_1, adj_B_2, adj_B_3, adj_B_4, adj_B_5, adj_B_6, adj_B_7,\n    output reg [31:0] min_cost\n);\n\nlocalparam MAX_N = 8;\nlocalparam MAX_M = 8;\n\nreg [7:0] adj_A [0:MAX_N-1];\nreg [7:0] adj_B [0:MAX_M-1];\nreg [3:0] dist_A [0:MAX_N-1][0:MAX_N-1];\nreg [3:0] dist_B [0:MAX_M-1][0:MAX_M-1];\n\nreg [15:0] cost_A, cost_B;\nreg [15:0] S_A [0:MAX_N-1];\nreg [15:0] S_A2 [0:MAX_N-1];\nreg [15:0] S_B [0:MAX_M-1];\nreg [15:0] S_B2 [0:MAX_M-1];\n\ninteger i, j, k, u, v, a, b;\nreg [15:0] cross_cost;\nreg [31:0] total_cost;\nreg [31:0] best_total;\n\nalways @(*) begin\n    // Assign adjacency inputs\n    adj_A[0] = adj_A_0; adj_A[1] = adj_A_1; adj_A[2] = adj_A_2; adj_A[3] = adj_A_3;\n    adj_A[4] = adj_A_4; adj_A[5] = adj_A_5; adj_A[6] = adj_A_6; adj_A[7] = adj_A_7;\n    adj_B[0] = adj_B_0; adj_B[1] = adj_B_1; adj_B[2] = adj_B_2; adj_B[3] = adj_B_3;\n    adj_B[4] = adj_B_4; adj_B[5] = adj_B_5; adj_B[6] = adj_B_6; adj_B[7] = adj_B_7;\n\n    // Initialize distance matrices\n    for (i = 0; i < MAX_N; i = i + 1) begin\n        for (j = 0; j < MAX_N; j = j + 1) begin\n            if (i == j) dist_A[i][j] = 4'd0;\n            else if (i < N && j < N && adj_A[i][j]) dist_A[i][j] = 4'd1;\n            else dist_A[i][j] = 4'd15;\n        end\n    end\n    for (k = 0; k < MAX_N; k = k + 1) begin\n        for (i = 0; i < MAX_N; i = i + 1) begin\n            for (j = 0; j < MAX_N; j = j + 1) begin\n                if (i < N && j < N && k < N && \n                    dist_A[i][k] + dist_A[k][j] < dist_A[i][j]) begin\n                    dist_A[i][j] = dist_A[i][k] + dist_A[k][j];\n                end\n            end\n        end\n    end\n\n    for (i = 0; i < MAX_M; i = i + 1) begin\n        for (j = 0; j < MAX_M; j = j + 1) begin\n            if (i == j) dist_B[i][j] = 4'd0;\n            else if (i < M && j < M && adj_B[i][j]) dist_B[i][j] = 4'd1;\n            else dist_B[i][j] = 4'd15;\n        end\n    end\n    for (k = 0; k < MAX_M; k = k + 1) begin\n        for (i = 0; i < MAX_M; i = i + 1) begin\n            for (j = 0; j < MAX_M; j = j + 1) begin\n                if (i < M && j < M && k < M && \n                    dist_B[i][k] + dist_B[k][j] < dist_B[i][j]) begin\n                    dist_B[i][j] = dist_B[i][k] + dist_B[k][j];\n                end\n            end\n        end\n    end\n\n    // Compute cost_A\n    cost_A = 16'd0;\n    for (i = 0; i < MAX_N; i = i + 1) begin\n        for (j = i + 1; j < MAX_N; j = j + 1) begin\n            if (i < N && j < N) begin\n                cost_A = cost_A + (dist_A[i][j] * dist_A[i][j]);\n            end\n        end\n    end\n\n    // Compute cost_B\n    cost_B = 16'd0;\n    for (i = 0; i < MAX_M; i = i + 1) begin\n        for (j = i + 1; j < MAX_M; j = j + 1) begin\n            if (i < M && j < M) begin\n                cost_B = cost_B + (dist_B[i][j] * dist_B[i][j]);\n            end\n        end\n    end\n\n    // Compute S_A and S_A2\n    for (u = 0; u < MAX_N; u = u + 1) begin\n        S_A[u] = 16'd0;\n        S_A2[u] = 16'd0;\n        if (u < N) begin\n            for (a = 0; a < MAX_N; a = a + 1) begin\n                if (a < N) begin\n                    S_A[u] = S_A[u] + dist_A[a][u];\n                    S_A2[u] = S_A2[u] + (dist_A[a][u] * dist_A[a][u]);\n                end\n            end\n        end\n    end\n\n    // Compute S_B and S_B2\n    for (v = 0; v < MAX_M; v = v + 1) begin\n        S_B[v] = 16'd0;\n        S_B2[v] = 16'd0;\n        if (v < M) begin\n            for (b = 0; b < MAX_M; b = b + 1) begin\n                if (b < M) begin\n                    S_B[v] = S_B[v] + dist_B[b][v];\n                    S_B2[v] = S_B2[v] + (dist_B[b][v] * dist_B[b][v]);\n                end\n            end\n        end\n    end\n\n    // Find minimal total cost\n    best_total = 32'hFFFFFFFF;\n    for (u = 0; u < MAX_N; u = u + 1) begin\n        if (u < N) begin\n            for (v = 0; v < MAX_M; v = v + 1) begin\n                if (v < M) begin\n                    cross_cost = (M * S_A2[u]) + (N * S_B2[v]) + (N * M) + \n                                  (2 * S_A[u] * S_B[v]) + (2 * M * S_A[u]) + (2 * N * S_B[v]);\n                    total_cost = {16'd0, cost_A} + {16'd0, cost_B} + {16'd0, cross_cost};\n                    if (total_cost < best_total) begin\n                        best_total = total_cost;\n                    end\n                end\n            end\n        end\n    end\n\n    min_cost = best_total;\nend\n\nendmodule